package com.wizzadrds.theworldremembers.behavior;
import com.wizzadrds.theworldremembers.personality.*; import com.wizzadrds.theworldremembers.relationship.*; import com.wizzadrds.theworldremembers.stress.NpcStress; import org.junit.jupiter.api.Test; import java.util.UUID; import static org.junit.jupiter.api.Assertions.*;
class NpcBehaviorEngineTest { @Test void sleepingNpcIgnores(){var r=new Relationship(UUID.randomUUID(),UUID.randomUUID(),80,80,0,80,80,0,0);assertEquals(NpcDecision.IGNORE_PLAYER,new NpcBehaviorEngine().decide(NpcActivity.SLEEPING,r,PersonalityGenerator.generate(r.npcId()),new NpcStress(0)));} @Test void criticalStressLeaves(){var r=new Relationship(UUID.randomUUID(),UUID.randomUUID(),80,0,0,0,0,0,0);assertEquals(NpcDecision.LEAVE,new NpcBehaviorEngine().decide(NpcActivity.IDLE,r,PersonalityGenerator.generate(r.npcId()),new NpcStress(100)));} @Test void resentmentOverridesFriendlyContext(){var r=new Relationship(UUID.randomUUID(),UUID.randomUUID(),0,0,0,0,0,0,60); var p=new PersonalityProfile(r.npcId()); assertEquals(NpcDecision.ACKNOWLEDGE_PLAYER,new NpcBehaviorEngine().decide(NpcActivity.IDLE,r,p,new NpcStress(0)));}}
